css:
.sl-cta-course {
    padding-block: clamp(3rem, 6vw, 5rem);
    border-block: 1px solid var(--smartlearn-card-border);
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-cta-course .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-cta-course .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-cta-course .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-cta-course.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-cta-course .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; }
.sl-cta-course .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-cta-course .sl-course-thumb { width: 120px; height: 120px; }
.sl-cta-course .sl-course-price { font-weight: 800; }
.sl-cta-course .sl-course-action { min-width: 180px; }
.sl-cta-course .sl-cert-badge {
    background-color: var(--smartlearn-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
    color: var(--smartlearn-primary);
    border: 1px solid color-mix(in srgb, var(--smartlearn-primary) 30%, transparent);
}
.sl-cta-course .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg) !important;
    border-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}
.sl-cta-course .sl-btn-primary:hover,
.sl-cta-course .sl-btn-primary:focus-visible {
    transform: translateY(-2px);
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.18) !important;
}
.sl-cta-course .sl-btn-primary:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
.sl-cta-course .sl-meta-item { display: inline-flex; align-items: center; }
.sl-cta-course .sl-meta-item:not(:last-child)::after {
    content: "•";
    margin-inline-start: 0.75rem;
    opacity: 0.4;
}
@media (min-width: 768px) {
    .sl-cta-course .sl-course-action {
        border-inline-start: 1px solid var(--smartlearn-card-border);
    }
}
@media (max-width: 767.98px) {
    .sl-cta-course .sl-course-action {
        width: 100%;
        border-block-start: 1px solid var(--smartlearn-card-border);
        padding-top: 1.5rem;
    }
    .sl-cta-course .sl-meta-item:not(:last-child)::after { display: none; }
    .sl-cta-course .sl-meta-item {
        border: 1px solid var(--smartlearn-card-border);
        padding: 2px 8px;
        border-radius: 4px;
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-cta-course .sl-btn-primary { transition: none; }
    .sl-cta-course .sl-btn-primary:hover,
    .sl-cta-course .sl-btn-primary:focus-visible { transform: none; }
}
